syntax:
template<class T>
bool std::atomic_compare_exchange_strong_explicit(
    std::atomic<T>* obj,
    T* expected,
    T desired,
    std::memory_order success,
    std::memory_order failure
);
// Implementation notes: 'obj' must be an atomic object; 'expected' is the value expected in 'obj'; 'desired' is the new value if the exchange succeeds. The compiler ensures atomicity via hardware instructions and inserts barriers based on 'success' and 'failure' memory orders, e.g., for memory_order_seq_cst, it adds full fences.

code_example:
#include <atomic>
#include <iostream>
#include <thread>

int main() {
    std::atomic<int> counter(0);
    int expected = 0;
    bool success = std::atomic_compare_exchange_strong_explicit(
        &counter,
        &expected,
        1,
        std::memory_order_seq_cst,  // Success order
        std::memory_order_seq_cst   // Failure order
    );
    if (success) {
        std::cout << "Exchange succeeded: " << counter.load() << std::endl;
    } else {
        std::cout << "Exchange failed: expected was " << expected << std::endl;
    }
    return 0;
}
